312	    router.get('/api/repositories/:id/credential-options', (
313	        _req: IncomingMessage,
314	        res: ServerResponse,
315	        params: Record<string, string>,
316	    ): void => {
317	        const id = params['id'];
318	
319	        const repo = resolveRepository(res, id);
320	        if (repo === undefined) return;
321	
322	        const credentials: GitCredentialEntry[] = appConfig.gitCredentials ?? [];
323	        const repoHost = extractHost(repo.Url);
324	
325	        // Filter to credentials whose host matches the repository's URL host.
326	        // For non-HTTPS URLs (e.g. SSH), repoHost is null and no credentials match.
327	        const matching = repoHost !== null
328	            ? credentials.filter((c) => c.host === repoHost)
329	            : [];
330	
331	        // Mask tokens before sending — never expose raw tokens over the API.
332	        const maskedCredentials: GitCredentialEntry[] = matching.map((c) => ({
333	            ...c,
334	            token: '***',
335	        }));
336	
337	        const responseBody: { credentials: GitCredentialEntry[]; autoSelected?: string } = {
338	            credentials: maskedCredentials,
339	        };
340	
341	        if (matching.length === 1) {
342	            responseBody.autoSelected = matching[0].id;
343	        }
344	
345	        sendJson(res, 200, responseBody);
346	    });
347	}

