 14	/**
 15	 * Minimal implementation of the RepositoryManager interface used by the routes.
 16	 * All methods are replaceable stubs.
 17	 */
 18	class MockRepositoryManager {
 19	    private store: Repository[] = [];
 20	
 21	    list(): Repository[] {
 22	        return this.store;
 23	    }
 24	
 25	    getById(id: string): Repository | undefined {
 26	        return this.store.find((r) => r.Id === id);
 27	    }
 28	
 29	    exists(id: string): boolean {
 30	        return this.getById(id) !== undefined;
 31	    }
 32	
 33	    add(params: { url: string; name?: string; id?: string }): Repository {
 34	        const id = params.id ?? 'inferred-id';
 35	        const name = params.name ?? id;
 36	
 37	        const duplicate = this.store.find((r) => r.Id === id);
 38	        if (duplicate) {
 39	            throw new Error(`A repository with ID "${id}" already exists.`);
 40	        }
 41	
 42	        const duplicateUrl = this.store.find((r) => r.Url === params.url);
 43	        if (duplicateUrl) {
 44	            throw new Error(`A repository with URL "${params.url}" already exists (ID: "${duplicateUrl.Id}").`);
 45	        }
 46	
 47	        const repo: Repository = { Id: id, Name: name, Url: params.url };
 48	        this.store.push(repo);
 49	        return repo;
 50	    }
 51	
 52	    update(id: string, params: { name: string }): Repository {
 53	        const index = this.store.findIndex((r) => r.Id === id);
 54	        if (index === -1) {
 55	            throw new NotFoundError(`Cannot update: repository with ID "${id}" does not exist.`);
 56	        }
 57	        this.store[index] = { ...this.store[index], Name: params.name };
 58	        return this.store[index];
 59	    }
 60	
 61	    remove(id: string): void {
 62	        const index = this.store.findIndex((r) => r.Id === id);
 63	        if (index === -1) {
 64	            throw new NotFoundError(`Cannot remove: repository with ID "${id}" does not exist.`);
 65	        }
 66	        this.store.splice(index, 1);
 67	    }
 68	
 69	    updateCredential(id: string, credentialId: string | null): Repository {
 70	        const index = this.store.findIndex((r) => r.Id === id);
 71	        if (index === -1) {
 72	            throw new NotFoundError(`Cannot update credential: repository with ID "${id}" does not exist.`);
 73	        }
 74	        const existing = this.store[index];
 75	        if (credentialId === null) {
 76	            const { CredentialId: _removed, ...rest } = existing;
 77	            this.store[index] = rest as Repository;
 78	        } else {
 79	            this.store[index] = { ...existing, CredentialId: credentialId };
 80	        }
 81	        return this.store[index];
 82	    }
 83	
 84	    // Test helper: seed the store directly
 85	    seed(repos: Repository[]): void {
 86	        this.store = [...repos];
 87	    }
